import re

def validate_credit_card(number):
    pattern = re.compile(r'^[456]\d{3}(-?\d{4}){3}$')
    if not pattern.match(number):
        return False

    group_pattern = re.compile(r'(.)\1\1\1')
    for part in number.replace('-', ''):
        if group_pattern.search(part):
            return False

    return True

N = int(input())
