def infected_zeroes(lst):
    turns = 0
    while True:
        new_lst = lst[:]
        infected = False
        for i in range(len(lst)):
            if lst[i] == 0:
                continue
            if i > 0 and lst[i - 1] == 0:
                new_lst[i] = 0
                infected = True
            if i < len(lst) - 1 and lst[i + 1] == 0:
                new_lst[i] = 0
                infected = True
        if not infected:
            break
        lst = new_lst
        turns += 1
    return turns
